(self.webpackChunkeduxio=self.webpackChunkeduxio||[]).push([["534"],{4706(e,t,n){e.exports={src:{srcSet:n.p+"assets/ideal-img/threeways.3980322.640.png 640w,"+n.p+"assets/ideal-img/threeways.3ef8808.1030.png 1030w",images:[{path:n.p+"assets/ideal-img/threeways.3980322.640.png",width:640,height:360},{path:n.p+"assets/ideal-img/threeways.3ef8808.1030.png",width:1030,height:579}],src:n.p+"assets/ideal-img/threeways.3980322.640.png",toString:function(){return n.p+"assets/ideal-img/threeways.3980322.640.png"},placeholder:void 0,width:640,height:360},preSrc:"data:image/png;base64,"}},1437(e,t,n){"use strict";n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>h,contentTitle:()=>d,toc:()=>p,assets:()=>c});var a=JSON.parse('{"id":"threeways","title":"Three Ways to Lead Learning","description":"by Gianpiero Petriglieri, HBR January-February 2025","source":"@site/docs/threeways.mdx","sourceDirName":".","slug":"/threeways","permalink":"/library/threeways","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Three Ways to Lead Learning","pagination_prev":null,"pagination_next":null}}'),i=n(4848),s=n(8453),o=n(1511),r=n(4706),l=n.n(r);let h={title:"Three Ways to Lead Learning",pagination_prev:null,pagination_next:null},d,c={},p=[{value:"Custodians",id:"custodians",level:2},{value:"Challengers",id:"challengers",level:2},{value:"Connectors",id:"connectors",level:2},{value:"Finding the Best Fit",id:"finding-the-best-fit",level:2},{value:"Which Approach Is Best for Your Organization?",id:"which-approach-is-best-for-your-organization",level:3}];function g(e){let t={a:"a",blockquote:"blockquote",em:"em",h2:"h2",h3:"h3",hr:"hr",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"by Gianpiero Petriglieri, HBR January-February 2025"})}),"\n",(0,i.jsxs)(t.p,{children:["Source (magazine article): ",(0,i.jsx)(t.a,{href:"https://hbr.org/2025/01/three-ways-to-lead-learning",children:"Three Ways to Lead Learning"}),(0,i.jsx)("br",{}),"\r\nHBR podcast with Gianpiero Petriglieri: ",(0,i.jsx)(t.a,{href:"https://hbr.org/podcast/2025/02/how-leaders-can-encourage-learning",children:"How Leaders Can Encourage Learning"})]}),"\n",(0,i.jsx)(o.A,{img:l()}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:"Over the past 25 years executives have become fervent advocates of learning, calling it an imperative, career insurance, and the only source of competitive advantage. That enthusiasm is warranted: Today the development of new skills, knowledge, and mindsets is critical to most businesses' key strategic efforts \u2014 from navigating global crises and unprecedented industry change, addressing the rise of generative AI, and driving innovation, to attracting and retaining talent, building inclusive workplaces, and making a positive difference in society."}),"\n",(0,i.jsx)(t.p,{children:"Indeed, more and more business leaders are moved to make a bold promise: that their company is not just a machine to deliver profit but also a community devoted to social impact and its members' well-being. Learning is key to fulfilling that promise, especially in an age when talent flocks to organizations that offer to upskill employees and support their development. A commitment to learning is critical to making organizations both more efficient and more humane."}),"\n",(0,i.jsxs)(t.p,{children:["The growing importance of learning has heralded the arrival of a new breed of senior leaders \u2014 people I call ",(0,i.jsx)(t.em,{children:"leaders of learning."})," They may be chief learning officers, heads of learning and development, heads of talent and organizational development, and in some companies, chief human resources or chief people officers. They advocate for and organize learning, developing learning strategies and implementing learning initiatives for the enterprise and its employees."]}),"\n",(0,i.jsx)(t.p,{children:'But many of their efforts are going awry. Academic studies reveal mixed evidence on whether such initiatives produce lasting individual or organizational change. Despite their public commitment to learning, in private many executives I meet express skepticism about the quality and effectiveness of it in their workplace. "How do I know this has any impact on my company\'s transformation?" I often hear. And there\'s skepticism from employees as well: "My boss doesn\'t actually care about my learning, just about results" is a common complaint.'}),"\n",(0,i.jsx)(t.p,{children:"Throughout my career I've taught, coached, and collaborated closely with leaders of learning. I've watched their excitement turn to frustration as their efforts were met with ambivalence and resistance or failed to deliver after raising much hope. To find out why so many are stymied \u2014 and what can be done about it \u2014 I teamed up with Annie Peshkam, a learning researcher and coach, to interview leaders of learning at 69 multinational firms across industries and continents."}),"\n",(0,i.jsx)(t.p,{children:"One of our key findings is that companies begin to stifle learning when executives assume that there's a single right way to do it that will serve all the organization's needs. That's simply not the case. We found that there are three distinct ways to lead learning \u2014 as a custodian, a challenger, or a connector \u2014 all of which can be successful in the right context. The methods used by leaders with the three approaches don't vary much; they all involve a combination of formal workshops, on-the-job learning, cases, speakers, 360-degree feedback, and so on. But how and why leaders deploy them differs dramatically. And we found that too often the intent of learning was unclear in organizations, resulting in a mismatch between the learning approach and current company needs. That caused friction and frustration and derailed efforts to improve learning."}),"\n",(0,i.jsx)(t.p,{children:"Understanding the three approaches and the differing goals they serve can help executives select, develop, partner with, and be better leaders of learning for their companies."}),"\n",(0,i.jsx)(t.h2,{id:"custodians",children:"Custodians"}),"\n",(0,i.jsx)(t.p,{children:"Custodians see learning as instrumental to executing an organization's strategy and strengthening its culture. In their view learning is a tool to help employees perform their roles better (and get better roles). While learning helps employees succeed and advance, the ultimate beneficiary is the organization, and any learning that doesn't provide a concrete advantage to the company is probably useless. Custodians embrace this view because they see themselves primarily as stewards of the business. For them, alignment with senior leadership is a top priority; they create value by bringing others on board with the top team's agenda. Indeed, many custodians we spoke to were business leaders in other areas before they came to learning, and most noted how much they had in common with their C-suite peers."}),"\n",(0,i.jsx)(t.p,{children:"Instrumental learning gets people to converge toward a norm, be it a cultural framework or a competency framework. Employees are assessed against a clear model and then get assignments meant to fill any gaps identified and build cultural cohesion. (A major concern of a custodian is thus picking the right people for the right learning at the right time.)"}),"\n",(0,i.jsx)(t.p,{children:'Custodians prefer centrally developed boot-camp-type learning that facilitates the deliberate acquisition and practice of new skills. Courses replicate the actual workplace, offer employees timely feedback on their practice attempts, and allow them to try again. The goal is for people to efficiently gain facility with new or difficult skills. Learning experiences are explicitly connected to the company\'s strategy and culture, since custodians disdain initiatives that are "too academic," or too distant from immediate application in the company. In the right contexts programs designed like this help participants strengthen their skills and rise up the ranks and help the company grow.'}),"\n",(0,i.jsx)(t.p,{children:"A classic example of the custodian approach is Apple University. Aware that the company was growing fast and that he would soon let go of its reins, Steve Jobs hired Joel Podolny, then the dean of the Yale School of Management, to develop a bespoke curriculum to socialize employees in Apple's unique ways of making decisions, communicating, and building products \u2014 and teach them the fundamental principles of simplicity, usefulness, and intuitiveness that Jobs held dear."}),"\n",(0,i.jsx)(t.p,{children:"The custodians we spoke with were most successful and most satisfied in companies where there was a pressing need for alignment \u2014 for example, following the launch of a new strategy or after a period of fast growth that had strained coordination across the firm. In such circumstances custodians can bring much-needed standardization and strengthen the common culture through their approach to learning. But we have seen custodians suddenly be fired, too \u2014 for example, when a new CEO determines that the company's learning approach is too rigid, stifling innovation or overlooking talent whose views might benefit the organization."}),"\n",(0,i.jsx)(t.h2,{id:"challengers",children:"Challengers"}),"\n",(0,i.jsx)(t.p,{children:"When CEOs want a learning leader who is less concerned with upholding standards and more focused on developing innovative capabilities, they often turn to a challenger. In contrast to custodians, challengers embrace a humanistic belief that employees have an intrinsic right to grow and forge their own paths and that the organization must honor that right. While the organization benefits from learning because it helps employees raise the quality of their work, challengers believe that the ultimate beneficiary must be the individuals themselves, or learning will become oppressive."}),"\n",(0,i.jsx)(t.p,{children:"Challengers often consider learning to be a moral duty of the organization rather than a financial one."}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"I believe that education is the way to help people grow personally and live a better life,"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"\u2014 one told us."}),"\n",(0,i.jsx)(t.p,{children:"Challengers tend to claim they have an \"outsider\" perspective that differs from the organization's mainstream thinking. They see themselves as valuable specialists who bring unique expertise to the C-suite \u2014 often with learning-focused r\xe9sum\xe9s. These leaders love telling stories of their peers' skepticism; friction with other senior leaders seems only to affirm their view that most executives are champions of the status quo who need redeeming rather than pleasing. That reflects challengers' perception that learning is valuable in helping people defy norms and break habits that hold the company back. While instrumental learning fosters convergence and alignment, humanistic learning encourages divergence from a norm."}),"\n",(0,i.jsx)(t.p,{children:"There are strong benefits to the challenger approach. The first is engagement: A number of challengers we spoke to reported proudly that employees they worked with had turned down higher-paid jobs offered by other companies, because they were afraid they would be made to conform and would lose the freedom they enjoyed. The second is innovation: Liberated, energized people are more likely to come up with new ways to do things. They can adapt global policies to local cultures. They do not wait for instructions to seize an opportunity or respond to a market turn. Most important, they are the restless, tinkering, internal champions of change that Clay Christensen believed were necessary in established companies, lest disruptive innovation from nimbler firms find them unprepared. It's perhaps ironic that while challengers report caring less about retention than custodians do, by making employees feel their skills are more portable, they improve it."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Companies begin to stifle learning when executives assume that there's a single right way to do it that will serve all the organization's needs."})}),"\n",(0,i.jsx)(t.p,{children:"If conformity stifles companies and silences employees, as challengers see it, then the boot camp typical of organizational learning often makes it worse. Humanistic learning, in contrast, is best pursued in a \u201Cplayground,\u201D where it's self-guided and more personalized. Employees choose what to learn and when on the basis of their interests, strengths, and personal goals; there is less emphasis on models, assessments, filling skill gaps, and the best practices of experts. When challengers program speakers, often they're luminaries outside the company's industry (artists, philosophers, other inspiring thinkers). When challengers offer classes, they favor workshops that help people reflect on the company's culture and their own habits, work, and interpersonal styles. Challengers frequently support talented employees who wish to pursue courses and programs outside the company's official offerings \u2014 be they cooking classes or spiritual retreats. Accountability comes from frank conversations about what those employees will do differently at work as a result of what they've learned."}),"\n",(0,i.jsx)(t.p,{children:"If military training is the obvious application of a boot camp, training for an architect or an artist would be an appropriate one for a playground. More and more companies are realizing that playgrounds are valuable for leadership development, too. A playground inherently allows people to acquire a larger variety of skills and viewpoints than they would at a boot camp-and develop the kind of agility and autonomy that's required to lead. In the right contexts, playgrounds foster new ideas, the questioning of norms, and changes in perspectives and relationships, allowing for not only innovative leaps in thinking but also holistic personal growth. Boot camps are best for acquiring new skills; playgrounds for developing new selves."}),"\n",(0,i.jsxs)(t.p,{children:["Laszlo Bock's ",(0,i.jsx)(t.em,{children:"Work Rules!,"}),' which is based on his experience as the head of people operations at Google, can be read as a challenger manifesto. The title of a central chapter, "Let the Inmates Run the Asylum," captures challengers\' view of organizations and their intent in them. The learning initiatives Bock describes throughout the book are all based on one principle: The more freedom leaders provide and the more attention they put on the growth and aspirations of each individual, the more attractive a company becomes to talent and the more likely that talent is to have new ideas and turn them into breakthrough products.']}),"\n",(0,i.jsx)(t.p,{children:'Bock\'s approach worked wonders for Google at a time when the company was set on building an innovation engine and competed fiercely for talent. But those are not the only circumstances in which it works. Challengers are most successful and satisfied in companies that are hungry for change. Those could be firms in which strong traditions or a stretch of success has made people cautious or complacent. In such circumstances challengers have the most impact and experience the fewest clashes with their executive teams. The most successful challengers are often prot\xe9g\xe9s of CEOs or CHROS who want "something different" and value professional expertise.'}),"\n",(0,i.jsx)(t.p,{children:"It's worth noting that while many CEOs are uneasy being champions of this approach themselves, they do want it to be represented on their teams, so they hire challengers but don't give them enough support. That kind of ideological tokenism is a recipe for failure. And like custodians, challengers can fall out of favor when their work is no longer seen as constructively questioning the status quo but, rather, as a costly subversion."}),"\n",(0,i.jsx)(t.h2,{id:"connectors",children:"Connectors"}),"\n",(0,i.jsx)(t.p,{children:"Learning leaders in the third group, connectors, strive to integrate the business-minded approach of custodians with the person-focused approach of challengers. Working through the two conflicting sets of principles, connectors tend to cast themselves as bridges between established leaders at the company's core and emerging leaders at its periphery. Their aim is to turn the company into a community that is both effective and made individuals who act and grow authentically. Perhaps unsurprisingly, connectors are also some of the most seasoned leaders, who have experience with both instrumental and humanistic approaches."}),"\n",(0,i.jsx)(t.p,{children:"While our research wasn't based on a random sample, connectors do seem to be rarer than custodians or challengers. Connectors say their integrated approach requires striking a tricky balance but believe that focusing solely on results is dated and can stifle creativity, and that focusing solely on empowerment is inefficient and can strain coordination."}),"\n",(0,i.jsx)(t.p,{children:"Like custodians, connectors favor initiatives that are anchored in a strategic imperative for the company. However, they pay particular attention to those that require the collaboration of different groups, because they prioritize building employees' mutual connections rather than their connection to the organization."}),"\n",(0,i.jsx)(t.p,{children:"Like challengers, connectors usually incorporate personalized learning opportunities into their courses and workshops. They encourage employees to see tackling a corporate challenge as a vehicle for their own personal and professional growth. Yet connectors place a unique emphasis on using learning experiences to bring people together, specifically to allow them to learn about and from one another \u2014 and they see such exchanges as potentially more valuable than the educational content itself. I call this a \"town hall\" approach. Connectors value high-quality facilitation of conversations among executives \u2014 for example, about solving a thorny innovation problem \u2014 for two reasons. First, they believe that's how the organization can best figure out how to overcome hurdles. Second, even if an idea that springs from such discussions doesn't get implemented, the relationships built while working on it might endure and serve people and the company well in the future."}),"\n",(0,i.jsx)(t.p,{children:"When the CEO of the global energy specialist Schneider Electric set the company on a path toward digital transformation, its head of talent, inclusion, and culture, Tina Mylon, championed a seven-year learning initiative called Transforming Schneider Leadership, or TSL (which I played a part in designing and delivering). It was built on the core principle that transformation should be the business not of individual leaders but of a leadership community. TSL provided a space for Schneider's executives to think and relate in new ways, through an intensive experiential workshop that took a playground approach, while also helping them develop the skills for implementing a digital strategy, through a digital boot camp at which people acquired and practiced using specific innovation tools. Since the program began, the company has tripled in value and grown into a provider of innovative and sustainable energy-management solutions. The organization is prized for its diversity and has improved retention and increased internal promotions. There's no way of knowing how much of that success is directly attributable to TSL, but Mylon has in that time reported seeing the company's extended pool of leaders grow \"more diverse, skilled, and impactful, and more connected to each other,\" something that has served the company well in its cross-unit innovation and culture efforts."}),"\n",(0,i.jsx)(t.p,{children:"Connectors are most successful and satisfied in companies where inclusion is a top priority-companies where community building is necessary to sustain a healthy leadership pipeline or to integrate the values and views of different groups. These are organizations where the viability of the business and the vitality of the community are understood to go hand in hand-which would be most companies, when you think about it."}),"\n",(0,i.jsx)(t.p,{children:"In my experience, custodians frequently are assumed to be the best fit for business, and as noted, challengers are often hired as tokens of innovative thinking but given little support. It seems to me that both those patterns stem from the fact that most businesses focus excessively on alignment and as a result wrestle with innovation, inclusion, and sustainability. With their integrative approach, connectors help companies overcome those problems."}),"\n",(0,i.jsx)(t.p,{children:"But connectors aren't perfect. Their work is criticized as being inefficient, and it surely takes time. They also often mentioned that it was a struggle to hold instrumental and humanistic views of learning simultaneously. And in circumstances where community building isn't a priority, connectors can appear unfocused. When introduced to the three types, some executives have even told me that they do not believe connectors really exist \u2014 that they're just custodians or challengers without enough discipline or enough courage to state their convictions. Perhaps those executives are simply skeptical that a company might truly honor both instrumental and humanistic principles, doing well and doing good. Connectors view that skepticism as unfounded and work to overcome it."}),"\n",(0,i.jsx)(t.h2,{id:"finding-the-best-fit",children:"Finding the Best Fit"}),"\n",(0,i.jsx)(t.p,{children:"Understanding the three ways to lead learning can help you shift the conversation away from the methods and costs of educational initiatives and toward their values and aims. It can also help you grasp why the learning leaders you work with might be struggling: Custodians and challengers can become embattled when people disagree with their preferred approach, and connectors often internalize the tension between the different views of learning."}),"\n",(0,i.jsx)(t.p,{children:"Awareness of the various approaches can help learning leaders make the case for their initiatives, to the benefit of the firm."}),"\n",(0,i.jsx)(t.h3,{id:"which-approach-is-best-for-your-organization",children:"Which Approach Is Best for Your Organization?"}),"\n",(0,i.jsx)(t.p,{children:"There are three distinct ways to lead learning, each of which can be successful in the right context."}),"\n",(0,i.jsxs)(t.table,{children:[(0,i.jsx)(t.thead,{children:(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.th,{}),(0,i.jsx)(t.th,{children:(0,i.jsx)(t.strong,{children:"CUSTODIAN"})})]})}),(0,i.jsxs)(t.tbody,{children:[(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Orientation"})}),(0,i.jsx)(t.td,{children:"Instrumental"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Primary commitment is to..."})}),(0,i.jsx)(t.td,{children:"Strategy and improving company performance"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Fits best in a company that is\u2026"})}),(0,i.jsx)(t.td,{children:"Changing and needs alignment"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Learning space"})}),(0,i.jsx)(t.td,{children:"Boot camp (convergent)"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"What users say"})}),(0,i.jsx)(t.td,{children:'"The ultimate outcome is that something changes in the job somebody is doing. Learning needs to lead to a concrete business result.\u201D'})]})]})]}),"\n",(0,i.jsxs)(t.table,{children:[(0,i.jsx)(t.thead,{children:(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.th,{}),(0,i.jsx)(t.th,{children:(0,i.jsx)(t.strong,{children:"CHALLENGER"})})]})}),(0,i.jsxs)(t.tbody,{children:[(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Orientation"})}),(0,i.jsx)(t.td,{children:"Humanistic"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Primary commitment is to..."})}),(0,i.jsx)(t.td,{children:"Helping individual people develop and grow"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Fits best in a company that is\u2026"})}),(0,i.jsx)(t.td,{children:"Stuck and needs innovation"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Learning space"})}),(0,i.jsx)(t.td,{children:"Playground (divergent)"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"What users say"})}),(0,i.jsx)(t.td,{children:'"The higher priority is creating healthier and happier workplaces; the secondary gain will be better business performance."'})]})]})]}),"\n",(0,i.jsxs)(t.table,{children:[(0,i.jsx)(t.thead,{children:(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.th,{}),(0,i.jsx)(t.th,{children:(0,i.jsx)(t.strong,{children:"CONNECTOR"})})]})}),(0,i.jsxs)(t.tbody,{children:[(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Orientation"})}),(0,i.jsx)(t.td,{children:"Both"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Primary commitment is to..."})}),(0,i.jsx)(t.td,{children:"Building a strong community"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Fits best in a company that is\u2026"})}),(0,i.jsx)(t.td,{children:"Siloed and needs collaboration"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Learning space"})}),(0,i.jsx)(t.td,{children:"Town hall (bounded divergence)"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"What users say"})}),(0,i.jsx)(t.td,{children:'"People want to come together but not to have a hundred PowerPoint slides thrown at them. They want to come together to build a community and learn from each other."'})]})]})]}),"\n",(0,i.jsx)(t.p,{children:"When a learning leader I worked with, whom I'll call Mark, took the role of director of corporate learning and development at a large global firm, he was given a bold challenge: Increase internal hires to 75% of all appointments for top roles by better preparing existing talent for leadership. Through Mark's connector lens, the problem was evident: The current talent-management process was disjointed. While some business groups and regions had knowledge about how to develop leaders, the organization lacked a common framework that established which skills the company's leaders needed and how they should acquire them, and aspiring leaders were mostly isolated in their individual divisions."}),"\n",(0,i.jsx)(t.p,{children:'Mark proposed engaging all the company\'s learning-and-development professionals and leaders to create that framework together and proposed a suite of collaborative global programs as a vehicle for building relationships across leadership generations. The senior management team resisted. Surely this was a competence problem; how would connecting people spur leadership? "It was the worst meeting of my whole career," Mark recalls.'}),"\n",(0,i.jsx)(t.p,{children:"But a friend helped him see the meeting as a reflection of the very challenge he was working to address: He needed to help senior executives let go of their custodian strategy, in which they were the gatekeepers for all learning and development, and collaborate to develop talent. Mark recast his strategy in this way, and a few months later it received a green light. And in time it has delivered. During Mark's tenure, leadership development has come to span all regions and business groups-and the percentage of senior leadership roles filled by internal candidates has reached the company's target. In a recent round of top management appointments, 100% were internal candidates, saving the company money and raising its profile as a workplace where talent is given opportunities to develop and lead."}),"\n",(0,i.jsx)(t.p,{children:"Whether you're hiring a new learning leader or trying to understand the dynamics of the one your company has in place now, ask yourself: What is your organization trying to accomplish? Does your team (or division or organization) need to execute on a clear vision, or does it need to forge a broader one? Is the learning required to make progress more instrumental or more humanistic? What is needed to promote the right combination of those approaches for your organization? Answering those questions might help you find the learning leadership that can bring that vision to life.\u{1F51A}"})]})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(g,{...e})}):g(e)}}}]);